responses = ["Yes", "No", "Yes", "Unknown", "Yes"]
yes = 0
known = 0
for response in responses:
    if response == "Yes" or response == "No":
        known = known + 1
        if response == "Yes":
            yes = yes + 1
if known > 0:
    print(yes / known)
else:
    print("No known responses")
